function draw(ctx, hit) {
  ctx.clearRect(0, 0, 800, 500);
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, 800, 500);
  ctx.fillStyle = "#111111";
  ctx.strokeStyle = "#111111";
  ctx.lineWidth = 2;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = "bold 20px Arial";
  ctx.fillText("Player 3 (B)", 400, 65);
  hit("player3-title", 320, 45, 160, 40);

  const x = 250, y = 150, cw = 180, ch = 120;
  ctx.font = "18px Arial";

  ["L", "R"].forEach((label, c) => {
    const cx = x + c * cw + cw / 2;
    ctx.fillText(label, cx, y - 30);
    hit(`column-${label}`, cx - 35, y - 50, 70, 40);
  });

  ["U", "D"].forEach((label, r) => {
    const cy = y + r * ch + ch / 2;
    ctx.fillText(label, x - 55, cy);
    hit(`row-${label}`, x - 90, cy - 25, 70, 50);
  });

  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + 2 * cw, y);
  ctx.lineTo(x + 2 * cw, y + 2 * ch);
  ctx.lineTo(x, y + 2 * ch);
  ctx.closePath();
  ctx.moveTo(x + cw, y);
  ctx.lineTo(x + cw, y + 2 * ch);
  ctx.moveTo(x, y + ch);
  ctx.lineTo(x + 2 * cw, y + ch);
  ctx.stroke();

  const payoffs = [
    ["7,7,0", "1,6,1"],
    ["6,1,1", "0,0,1"]
  ];
  ctx.font = "20px Arial";
  payoffs.forEach((row, r) => {
    row.forEach((value, c) => {
      const cellX = x + c * cw;
      const cellY = y + r * ch;
      ctx.fillText(value, cellX + cw / 2, cellY + ch / 2);
      hit(`cell-r${r}-c${c}`, cellX, cellY, cw, ch);
    });
  });
}

