  ctx.textAlign = "center";
  for (let c = 0; c < cols; c++) {
    const x = left + c * cellW + cellW / 2;
    ctx.fillText("c" + (c + 1), x, top - 18);
    hit("column-c" + (c + 1), left + c * cellW, top - 32, cellW, 28);
  }

  ctx.textAlign = "right";
  for (let r = 0; r < rows; r++) {
    const y = top + r * cellH + cellH / 2;
    ctx.fillText("r" + (r + 1), left - 12, y);
    hit("row-r" + (r + 1), left - 72, top + r * cellH, 68, cellH);
  }

  ctx.strokeStyle = "#222222";
  ctx.lineWidth = 1.25;
  ctx.beginPath();
  for (let c = 0; c <= cols; c++) {
    const x = left + c * cellW;
    ctx.moveTo(x, top);
    ctx.lineTo(x, top + rows * cellH);
  }
  for (let r = 0; r <= rows; r++) {
    const y = top + r * cellH;
    ctx.moveTo(left, y);
    ctx.lineTo(left + cols * cellW, y);
  }
  ctx.stroke();

