function draw(ctx, hit) {
  ctx.clearRect(0, 0, 800, 500);
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, 800, 500);
  ctx.font = "16px Arial";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.lineWidth = 2;
  ctx.strokeStyle = "#222222";
  ctx.fillStyle = "#222222";

  const left = 100;
  const right = 700;
  const y = 270;
  const xFor = (position) => left + position * (right - left);

  ctx.beginPath();
  ctx.moveTo(left, y);
  ctx.lineTo(right, y);
  ctx.stroke();
  hit("city-line", left, y - 4, right - left, 8);

  for (const [id, position] of [["endpoint-0", 0], ["endpoint-1", 1]]) {
    const x = xFor(position);
    ctx.beginPath();
    ctx.moveTo(x, y - 12);
    ctx.lineTo(x, y + 12);
    ctx.stroke();
    ctx.fillText(String(position), x, y + 38);
    hit(id, x - 14, y - 16, 28, 60);
  }

  for (const vendor of [
    { id: "vendor-A", name: "A", position: 0.2 },
    { id: "vendor-B", name: "B", position: 0.8 }
  ]) {
    const x = xFor(vendor.position);
    ctx.beginPath();
    ctx.arc(x, y, 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillText(vendor.name, x, y - 38);
    ctx.fillText(String(vendor.position), x, y + 38);
    hit(vendor.id, x - 32, y - 52, 64, 102);
  }
}

