          </g>
        ))}

        <text data-id="x-axis-label" x="668" y="426" fontSize="18" fill={ink}>x</text>
        <text data-id="y-axis-label" x="400" y="78" textAnchor="middle" fontSize="18" fill={ink}>y</text>

        <polyline
